head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00900";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.lang

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_24_txt", fn: function(){ return ((dma_pageContext.get("lang") ?? "") === 'en'); } }, { id: "c_otherwise_25", fn: function(){ return (!(((dma_pageContext.get("lang") ?? "") === 'en'))); } }, { id: "c_when_58_txt", fn: function(){ return ((dma_pageContext.get("lang") ?? "") === 'en'); } }, { id: "c_otherwise_59", fn: function(){ return (!(((dma_pageContext.get("lang") ?? "") === 'en'))); } }, { id: "c_when_74_txt", fn: function(){ return ((dma_pageContext.get("lang") ?? "") === 'en'); } }, { id: "c_otherwise_75", fn: function(){ return (!(((dma_pageContext.get("lang") ?? "") === 'en'))); } }, { id: "c_otherwise_95", fn: function(){ return (!(((dma_pageContext.get("lang") ?? "") === 'en'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_54", entity: "dlt_disclosureViewMainDocuments", countIds: [], cells: [{ childId: "option_56", fn: function (v, i) { return String(v("disclsDocNo")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("modEngYn")) + " " + String(v("formEngNm")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("modYn")) + " " + String(v("formKorNm")); } }] },
        { genId: "c_foreach_70", entity: "dlt_disclosureViewAttachDocuments", countIds: [], cells: [{ childId: "option_72", fn: function (v, i) { return String(v("disclsDocNo")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("modEngYn")) + " " + String(v("formEngNm")); } }, { childId: "__rc5", fn: function (v, i) { return String(v("modYn")) + " " + String(v("formKorNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        if (($c.util.getComponent('slc_mainDoc').getValue() == null ? '' : String($c.util.getComponent('slc_mainDoc').getValue())) !== '') {
            await scwin.view("main", $c.util.getComponent('slc_mainDoc').getValue());
        } else {
            await scwin.view("attach", $c.util.getComponent('slc_attachDoc').getValue());
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00900.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil00900: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_viewForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00900.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_mainDoc_onchange
 * @description slc_mainDoc 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_mainDoc_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.changeDocument('main', selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00900.slc_mainDoc_onchange' }); }
};

/**
 * @method
 * @name slc_attachDoc_onchange
 * @description slc_attachDoc 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_attachDoc_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.changeDocument('attach', selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00900.slc_attachDoc_onchange' }); }
};

/**
 * @method
 * @name img_78_onclick
 * @description img_78 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_78_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00900.img_78_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_view_xhr
 * @description view xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_view_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_view_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_view_xhr", unresolved: "action:self_submit:tx_view_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name view
 * @description view 처리
 * @param {*} docDiv docDiv
 * @param {*} docNo docNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.view = async function (docDiv, docNo) {
    if (docNo === "") {
        return;
    }
    $c.util.getComponent('dma_viewXhrReq').set('docNo', docNo);
    $c.util.getComponent('dma_viewXhrReq').set('method', "findDisclosureDocument");
    scwin.form_viewForm.action = "/submission/disclosure.do";
    $c.util.getComponent('txt_contentDiv').setValue(await scwin.tx_view_xhr());
    $c.util.getComponent('txt_publDdDiv').setLabel(eval("viewForm." + docDiv + "Doc.options[document.viewForm." + docDiv + "Doc.options.selectedIndex]").publDd);
};

/**
 * @method
 * @name displayToc
 * @description display Toc 처리
 * @param {*} display display
 * @returns {void}
 * @hidden N
 */
scwin.displayToc = function (display) {
    if (display) {
        ($c.util.getComponent('tocDiv') && $c.util.getComponent('tocDiv').show ? $c.util.getComponent('tocDiv').show() : console.warn('[sdd] show 대상 미해결: ' + 'tocDiv'));
        ($c.util.getComponent('hiddenTocDiv') && $c.util.getComponent('hiddenTocDiv').hide ? $c.util.getComponent('hiddenTocDiv').hide() : console.warn('[sdd] hide 대상 미해결: ' + 'hiddenTocDiv'));
    } else {
        ($c.util.getComponent('tocDiv') && $c.util.getComponent('tocDiv').hide ? $c.util.getComponent('tocDiv').hide() : console.warn('[sdd] hide 대상 미해결: ' + 'tocDiv'));
        ($c.util.getComponent('hiddenTocDiv') && $c.util.getComponent('hiddenTocDiv').show ? $c.util.getComponent('hiddenTocDiv').show() : console.warn('[sdd] show 대상 미해결: ' + 'hiddenTocDiv'));
    }
};

/**
 * @method
 * @name changeDocument
 * @description change Document 처리
 * @param {*} docDiv docDiv
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeDocument = async function (docDiv, obj) {
    await scwin.view(docDiv, obj.value);
    if (docDiv === "main") {
        $c.util.getComponent("slc_attachDoc").setValue("");
    } else {
        $c.util.getComponent("slc_mainDoc").setValue("");
    }
    this.focus();
};
